input.script:
companies = boundary retry 2 {
    return list_companies({})
} catch err {
    return fail("COMPANIES_FAILED", err.code + ": " + err.message)
}
first = boundary retry 2 {
    return list_contacts({ page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    r = boundary retry 2 {
        return list_contacts({ page })
    } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return r.items
}
contacts = fold acc = first.items for page in remaining { return acc + page }

updates = for c in contacts {
    skip if c.id == null
    phone_raw = c.phone if c.phone != null else ""
    valid_phone = regex.test(phone_raw, "^[+]1[0-9]{10}$")
    digits = regex.replace(phone_raw, "[^0-9]", "")
    new_phone = if text.length(digits) == 10 {
        return "+1" + digits
    } else if text.length(digits) == 11 and text.starts_with(digits, "1") {
        return "+" + digits
    } else {
        return null
    }
    phone_fix = new_phone != null and not valid_phone
    email = c.email if c.email != null else ""
    domain = text.lower(text.split(email, "@")[1]) if "@" in email else ""
    matched = for co in companies {
        skip if co.domain == null
        skip if domain == ""
        skip if text.lower(co.domain) != domain
        skip if co.name == null
        return co.name
    }
    new_company = matched[0] if matched != [] else null
    company_empty = c.company == null or c.company == ""
    company_fix = company_empty and new_company != null
    u = boundary retry 2 {
        return update_contact({ id: c.id, phone: new_phone, company: new_company })
    } catch err {
        return fail("UPDATE_FAILED", err.code + ": " + err.message)
    } if (phone_fix or company_fix) and c.id != null
    return { phone_fix: phone_fix, company_fix: company_fix }
}

phones_fixed = fold acc = 0 for x in updates { return acc + (1 if x.phone_fix else 0) }
companies_filled = fold acc = 0 for x in updates { return acc + (1 if x.company_fix else 0) }
result = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed: phones_fixed, companies_filled: companies_filled, recorded: result.recorded }
